"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[62394],{62394:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/28.png\\"\\n          title=\\"28\\"\\n          author=\\"정유정\\"\\n          publisher=\\"은행나무\\"\\n          publishedDate=\\"2013-06-27\\"\\n          isbn=\\"9788956607030\\"\\n          rating=4\\n          tags=\\"thriller\\"\\n        />\\n</center>\\n\\n## Review\\n팬데믹이라는 상황 속에서 살아남고자 하는 인간들의 민낯을 잘 보여주는 작품이다.  \\n전염병 ```적안```이 개들 사이에 퍼져 나가고, 인간으로 전염되기 시작한다.  \\n<br>```개```들을 서슴없이 학살하는 인간들이 지독하게 묘사된다.  \\n이 책 또한 감정 소모가 심해 읽기 어려웠다.  \\n하지만 이러한 학살 장면은 작품 후반부에 ```인간```을 학살하는 장면과 오버랩된다.  \\n결국 인간은 자신들의 생존을 위해 <mark>종</mark>에 상관없이 학살 가능하다.  \\n<br>\\n이런 재난 상황이 자신과 상관없다 생각하는 인간들은 단지 이 상황을 소비한다.  \\n<mark>수전 손택 - 타인의 고통</mark>이 생각나는 장면이다.  \\n<br>\\n하지만 이러한 극한의 상황 속에서의 희망 또한 ```인간```임을 보여준다.  \\n<br>\\n소나 돼지가 아닌 반려동물과 인간 사이에 구제역보다 더 치명적인 인수공통전염병이 돈다면 가축에게 했던 것과 똑같은 짓을 할까? 작가의 대답은 \'그렇다\'이다.  \\n<br>\\n인간은 생태계 최고 포식자로서, 변덕쟁이 폭군이다.  \\n"}')}}]);